using System.Diagnostics;using Microsoft.EntityFrameworkCore;using OpenFlux.Zen.Server.Data;using OpenFlux.Zen.Server.Models;namespace OpenFlux.Zen.Server.Services;public sealed class TunnelManager(IServiceScopeFactory scopes,ILogger<TunnelManager> log){readonly Dictionary<Guid,Process> ps=new();readonly object gate=new();public async Task<IReadOnlyList<Tunnel>> All(){using var s=scopes.CreateScope();return await s.ServiceProvider.GetRequiredService<AppDbContext>().Tunnels.AsNoTracking().ToListAsync();}public async Task<Tunnel?> Get(Guid id){using var s=scopes.CreateScope();return await s.ServiceProvider.GetRequiredService<AppDbContext>().Tunnels.FindAsync(id);}public async Task<Tunnel> Save(Tunnel t){using var s=scopes.CreateScope();var db=s.ServiceProvider.GetRequiredService<AppDbContext>();if(t.Id==Guid.Empty)t.Id=Guid.NewGuid();db.Update(t);await db.SaveChangesAsync();return t;}public async Task<bool> Delete(Guid id){await Stop(id);using var s=scopes.CreateScope();var db=s.ServiceProvider.GetRequiredService<AppDbContext>();var t=await db.Tunnels.FindAsync(id);if(t is null)return false;db.Remove(t);await db.SaveChangesAsync();return true;}public async Task<bool> Start(Guid id){var t=await Get(id);if(t is null)return false;lock(gate){if(ps.ContainsKey(id))return true;}var a=System.Runtime.InteropServices.RuntimeInformation.OSArchitecture.ToString().ToLowerInvariant();var exe=Path.Combine(AppContext.BaseDirectory,"runtimes",OperatingSystem.IsWindows()?$"openflux-windows-{(a.Contains("arm")?"arm64":"amd64")}.exe":$"openflux-linux-{(a.Contains("arm")?"arm64":"amd64")}");if(!File.Exists(exe)){t.Status=TunnelStatus.Faulted;await Save(t);return false;}var psi=new ProcessStartInfo(exe){UseShellExecute=false,CreateNoWindow=true};foreach(var x in new[]{"-role",t.Role,"-transport",t.Transport,"-mode",t.Mode,"-inbound",t.Inbound,"-socks5",t.SocksAddress,"-debug"})psi.ArgumentList.Add(x);var p=Process.Start(psi);if(p is null)return false;lock(gate)ps[id]=p;t.Status=TunnelStatus.Running;t.LastStartedUtc=DateTime.UtcNow;await Save(t);log.LogInformation("Tunnel {Name} started",t.Name);return true;}public async Task<bool> Stop(Guid id){Process? p;lock(gate){ps.TryGetValue(id,out p);if(p is not null)ps.Remove(id);}if(p is not null){try{if(!p.HasExited)p.Kill(true);}catch{}p.Dispose();}var t=await Get(id);if(t is null)return false;t.Status=TunnelStatus.Stopped;await Save(t);return true;}public async Task RestoreEnabled(){foreach(var t in await All())if(t.Enabled)await Start(t.Id);}}
